"explanation": "ガス事業法第3条の2により、ガス小売事業を営もうとする者は経済産業大臣の登録を受けなければならない。2017年のガス小売全面自由化に伴い、新規参入を促進するため許可制より要件の緩やかな登録制が採用された。\n\nA：許可制は一般ガス導管事業・一般ガス製造事業に適用される手続きであり、ガス小売事業には適用されない。\nB：届出のみでは不十分。ガス小売事業は登録制であり、登録前の事業開始は禁止される。\nD：所轄庁は経済産業局長ではなく経済産業大臣であり、届出制でもない。\n\n【頻出】2017年のガス小売全面自由化は試験の背景知識として重要。自由化以前は地域独占の許可制だったが、自由化後は登録制となった。\n【混同注意】一般ガス導管事業（許可）とガス小売事業（登録）の区別は頻出。導管は公共インフラのため許可制が維持されている。"
