"explanation": "完全燃焼反応式CH₄ + 2O₂ → CO₂ + 2H₂Oより、メタン1分子の燃焼には酸素2分子が必要。気体は標準状態で等体積比がモル比に等しいため、メタン1m³の完全燃焼には酸素2m³が必要となる。\n\nA：酸素1m³では反応式の係数比（メタン：酸素＝1：2）に合わず不足。\nC：酸素3m³は過剰。反応式の係数比から酸素は2m³が正解。\nD：酸素4m³はさらに過剰。係数比の読み間違いによる誤答。\n\n【頻出】燃焼反応式の係数比から理論酸素量・空気量を求める計算は試験頻出。反応式の係数（CH₄:O₂ = 1:2）から直接酸素量を読み取る。\n【混同注意】理論酸素量（O₂量）と理論空気量（空気量）の違い。理論空気量＝理論酸素量÷0.21（空気中の酸素体積分率）。メタン1m³の理論空気量はおよそ9.5m³。"
