"explanation": "プロパンは無極性の炭化水素であり、水への溶解度は極めて低い（難溶性）。「水に溶けやすい」という記述は誤りである。プロパンは有機溶媒には溶けやすい。\n\nA：正しい。プロパンの沸点は約−42.1℃（常圧）であり、常温（20℃）では気体として存在する。\nB：正しい。プロパンの分子量は44であり空気（平均分子量29）より重く、空気に対する比重は約1.52。漏洩時は低所に滞留する。\nC：正しい。プロパンの爆発下限界（LEL）は約2.1%（体積）であり、上限界（UEL）は約9.5%である。\n\n【頻出】プロパンの爆発範囲（2.1%〜9.5%）とメタンの爆発範囲（5%〜15%）は数値として問われやすい。LPGの方が爆発下限界が低く、より低濃度で爆発する危険性がある。\n【混同注意】プロパンの爆発下限界（2.1%）はメタン（5%）より低く、より希薄な状態で爆発する点が重要。低い下限界＝より危険という関係を覚える。"
