"explanation": "一酸化炭素（CO）の分子量は28であり、空気の平均分子量（29）とほぼ同じか若干軽いため、空気と同様に分散しやすく「空気より重く床面滞留」という特性は持たない。特定の滞留傾向はなく、空間全体に広がる。\n\nA：正しい。COは無色・無臭であり人間の感覚（視覚・嗅覚）では検知できない。これがCO中毒の危険性を高める最大の理由。\nB：正しい。COの爆発範囲は12.5〜74vol%と広く、可燃性であることも重要な危険特性。\nC：正しい。COはヘモグロビンとの親和性が酸素の約200〜250倍であり、少量でも酸素運搬能力を大幅に阻害する。\n\n【頻出】CO中毒の機序（ヘモグロビンとの強結合→酸素運搬阻害）とCOの無色無臭特性はガス保安の最重要知識。CO検知器の設置義務の根拠ともなる。\n【混同注意】CO（分子量28、空気と同等）はプロパン（分子量44、空気より重い）と挙動が異なる。CO中毒は密閉空間・換気不十分な場所で多発する。"
