"explanation": "同族列では炭素数が増えるほど1分子中の炭素・水素原子数が増加し、完全燃焼時に放出されるエネルギーが増大する。エタン（C₂H₆、低発熱量約1558kJ/mol）はメタン（CH₄、約802kJ/mol）より1分子あたりの発熱量が大きく、体積あたり発熱量も同様に大きい。\n\nA：アルカン（パラフィン）は炭素-炭素「単結合」のみから構成される飽和炭化水素であり、比較的化学的に安定。二重結合を持つのはアルケン（オレフィン）系。\nC：アルケン（二重結合あり）はアルカン（単結合のみ）より化学的に反応性が高く不安定。「二重結合＝安定」は逆の関係。\nD：炭素数が増えると爆発下限界は一般に低下する傾向がある（例：メタン5%、プロパン2.1%、ブタン1.8%）。高炭素数ほど爆発危険性が高まる方向。\n\n【頻出】アルカン・アルケンの結合形式と化学的安定性の違いは有機化学の基礎。炭素数と爆発下限界の関係（炭素数増→下限界低下→危険性増）も試験頻出の傾向。\n【混同注意】発熱量は1分子あたりと単位体積あたりで比較の基準が異なる。都市ガス器具の設計では体積あたり発熱量（MJ/m³）が重要な指標となる。"
