"explanation": "絶縁継手（絶縁フランジ等）は、異種金属接続部での電位差腐食（ガルバニック腐食）やカソード防食電流の漏れを防ぐために設置されるものであり、「電流を増加させて腐食を促進させる」という効果は全く逆。絶縁継手は電流を遮断して腐食防止に寄与する。\n\nA：正しい防食対策。被覆防食は腐食環境と金属面を物理的に隔離する最も基本的な方法。\nB：正しい防食対策。流電陽極法（犠牲陽極法）は卑金属が優先的に溶解（腐食）することで被保護金属（鋼管）を陰極として保護する。\nC：正しい防食対策。外部電源式カソード防食は直流電源で被保護管に防食電流を供給し、管の電位を腐食が起こらないレベルに保つ。\n\n【頻出】埋設導管の防食対策（被覆防食・流電陽極法・外部電源法・絶縁継手）は供給設備保安の基礎として頻出。各方法の原理と目的を整理すること。\n【混同注意】絶縁継手は「電気的に絶縁する（電流を遮断する）」装置であり、電流を増加・促進するものではない。防食電流の管外漏洩防止と迷走電流対策として重要な設備。"
