"explanation": "整圧器（ガバナ：Governor/Pressure Regulator）は一次側（上流）の高い圧力を二次側（下流）の設定圧力に減圧・安定させる装置であり、需要量の変化（流量変化）に応じて弁体の開度を自動調整することで二次圧力を一定に保つ。\n\nB：整圧器が制御するのは下流側（二次側）の圧力であり、上流側圧力を一定に保つ装置ではない。整圧器は二次圧力（下流）を設定値に維持する。\nC：整圧器は一次圧力が変動しても弁体の自動調整によって二次圧力を一定に保つことが基本機能。自動調整機能を持たないという記述は誤り。\nD：整圧器と流量計は別々の装置。整圧器は流量計測機能を標準的には持たない。供給量（流量）の計測には別途流量計を設置する。\n\n【頻出】整圧器の基本機能（二次圧力を設定値に維持・需要変動に対する自動調整）はガス供給設備の理解の核心として頻出。一次圧（入口）と二次圧（出口）の区別も重要。\n【混同注意】整圧器（圧力調整・減圧）と緊急遮断弁（異常時遮断）は目的・機能が異なる装置。両者が組み合わせて設置されることが多いが、それぞれの役割を区別して理解する。"
