"explanation": "ガス導管の巡視は、保安規程に基づき導管路線を定期的に歩行または車両で確認し、地表面の沈下・隆起・ガス臭、他工事（道路工事・建設工事等）による損傷リスク、漏洩の兆候等の異常を早期に発見するために実施する。導管保安の基本的な活動の一つ。\n\nB：巡視は主に外観・地表面・臭気等の確認であり、ガスクロマトグラフィーによる組成分析は巡視の主目的ではない。組成分析は品質管理として別途実施される。\nC：巡視頻度はすべての路線で毎日義務付けられているわけではなく、保安規程・技術基準に定められた頻度（路線の重要度・状況等により異なる）で実施される。\nD：既設導管は年数が経つほど老朽化・腐食が進むため、むしろ継続的な巡視・点検が重要になる。「10年経過後は不要」という規定はなく、継続的な保安活動が求められる。\n\n【頻出】導管巡視の目的（地表変状・ガス臭・他工事による損傷リスク確認）と定期実施義務は供給設備保安の基本として頻出。巡視は目視・嗅覚等による現場確認活動である。\n【混同注意】巡視（定期的な現地確認・外観観察）と漏洩検査（ガス検知器等を使用した専門的な漏洩測定）は目的・方法・頻度が異なる保安活動。両者を組み合わせた保安体制が重要。"
