"explanation": "ガス工作物の技術上の基準を定める省令により、一般ガス導管事業者は需要者に供給するガスの圧力を所定の範囲（例：低圧供給では最高2.5kPa以下等）に維持する義務がある。圧力変動が大きい場合は機器の不完全燃焼・失火等の保安問題が生じる。\n\nA：供給圧力は法令・技術基準による規制を受けており、事業者の自由設定は認められない。圧力範囲の維持はガス工作物の技術基準の重要な要件。\nC：供給圧力は「一律0.1MPa固定」ではなく、供給区域・需要者の種別・ガス機器の仕様に応じた適切な範囲（例：家庭用低圧は1〜2.5kPa程度）で管理される。\nD：供給圧力の維持責任は事業者（一般ガス導管事業者）にある。需要者側は供給される圧力範囲でガス機器を使用する義務がある。\n\n【頻出】需要者への供給圧力の維持義務はガス事業者の基本的な技術的義務として頻出。供給圧力の範囲（低圧家庭用の数値等）も試験で問われる。\n【混同注意】供給圧力（需要者へのガス届け圧力）と配管内圧力（中圧・高圧幹線の管内圧力）は異なる概念。需要者宅前では整圧器等で低圧に減圧されて供給される。"
