"explanation": "都市ガス（主成分メタン、比重約0.55）は空気より軽いため天井付近に滞留する。このため漏洩検知器は天井から30cm以内の高所に設置することで早期検知が可能となる。LPG（プロパン・ブタン主体）は空気より重く床面付近に滞留するため低所（床から30cm以内）に設置する。\n\nA：床面付近への設置はLPG（重い・低所滞留）の検知器設置方法であり、都市ガス（軽い・高所滞留）には不適切。\nC：LPGは空気より重いため天井付近への設置は不適切。LPGは床面付近（低所）に検知器を設置することが有効。\nD：ガス種による比重の違いにより滞留位置が異なるため、設置高さの規定は「一律床から1m」ではなく、ガス種に応じた設置位置基準が定められている。\n\n【頻出】都市ガス検知器（天井付近）とLPG検知器（床面付近）の設置高さの違いはガス種の比重差に基づく最頻出事項。設置高さの根拠（比重差による滞留位置の違い）を理解する。\n【混同注意】都市ガス（軽い・高所）とLPG（重い・低所）の滞留挙動の違いは検知器設置だけでなく換気方法（高所換気vs低所換気）にも影響する。セットで覚えること。"
