"explanation": "排気筒（煙突・給排気管）の施工基準として、排気ガスが機器に逆流しないよう屋外に向かって水平または上り勾配（1/100以上等）で施工することが定められている。また排気筒長・エルボの数の上限も定められており、長すぎる・曲がりが多い施工は排気抵抗増大による不完全燃焼の原因となる。\n\nB：排気筒は必要最短長・最少曲がりで施工することが推奨される。長い排気筒・多数のエルボは排気抵抗を増大させ、排気不良・CO発生の原因となる。「長くすることが推奨」は誤り。\nC：排気筒の接続部はガムテープではなく専用の継手・固定バンド・断熱材等を使用して確実に固定・気密を確保しなければならない。排気ガスの漏洩防止が目的。\nD：排気筒の材質はステンレス鋼が広く使用されており、安全基準を満たす材料であれば使用可能。「ステンレス製は使用不可」という規定はない。フレキシブルアルミ製も使用されるが「最も適切で唯一」とは言えない。\n\n【頻出】排気筒の施工基準（勾配・長さの上限・エルボ数の上限・接続部の気密確保）はガス機器施工の基本として試験頻出。不適切な施工がCO中毒事故の原因となる実例も多い。\n【混同注意】排気筒の「上り勾配」（屋外方向へ上がる勾配：正しい施工）と「逆勾配・下り勾配」（屋外方向へ下がる勾配：排気ガスが機器側に逆流する危険な施工）の区別。"
