"explanation": "テーブルコンロの設置基準として、コンロ上方の可燃物（木製棚・キャビネット等）からの距離（有効空間：コンロ天板から上方80cm以上等）を確保することが求められる。可燃物への着火・過熱防止が目的。\n\nA：不燃材料であれば横に制限なく置けるという規定はなく、コンロの横・後方の可燃物についても一定の離隔が必要。可燃物の種類に応じた離隔基準が設けられている。\nC：コンロを設置する台（流し台・調理台等）は熱に耐えられる材質（不燃・難燃材料等）であることが安全上求められる。「どのような台でもよい」という無制限の設置基準はない。\nD：テーブルコンロのガス接続はガスコード（ゴム管・ソフトホース等）が広く使用されており、使用禁止の規定はない。ただしガスコードの種類・長さ・接続方法には基準が設けられている。\n\n【頻出】コンロ設置時の上方空間（有効空間）確保と可燃物からの離隔基準は厨房での火災防止の基本として頻出。コンロ周辺の可燃物配置が火災原因となる事例が多い。\n【混同注意】ガスコード（ゴム・樹脂製フレキシブル接続管）の使用は認められているが、接続長さの制限・劣化防止のための管理が必要。使用可能なガスコードの種類と適用範囲を確認する。"
