"explanation": "フレームロッド（イオン化炎検知）方式は、炎（燃焼プラズマ）中に多数のイオンと自由電子が存在することを利用する。バーナー（グラウンド）とフレームロッド（検知電極）間に高電圧（交流または直流）を印加すると、炎がある場合は炎中のイオンを通じて微弱な整流電流（直流成分）が流れ、この電流を検知して炎の有無を判断する。\n\nB：炎の光を光センサーで受光する方式は「光センサー式（紫外線・赤外線検知）」であり、フレームロッドの動作原理とは異なる。フレームロッドは電気的検知。\nC：磁気特性による検知はフレームロッドの動作原理ではない。炎は弱く磁性を持つが、通常の炎検知に磁気特性は使用されない。\nD：圧電素子による圧力変動検知はフレームロッドの原理ではない。炎の存在を圧力振動パターンで判断するという方法は通常の炎検知には使用されない。\n\n【頻出】フレームロッド（イオン化炎検知）の原理（炎中のイオンによる微弱電流）はガス機器の点火・炎確認システムとして試験頻出。熱電対式（起電力）とフレームロッド式（イオン電流）の区別も重要。\n【混同注意】フレームロッド（イオン電流検知・応答速度が速い）と熱電対（起電力検知・応答速度が遅い）の炎検知方式の違い。前者はインターロック・燃焼制御に、後者は立消え安全装置に主に使用される。"
