"explanation": "ガス給湯器の号数（能力）の定義は「1分間に水温を25℃上昇させることができる給湯量（L/min）」である。例えば16号給湯器は1分間に16Lの水を25℃上昇させる能力を持つ。これは水温を15℃（冬季水温）から40℃（適切な給湯温度）に上昇させる標準的な使用条件に基づいている。\n\nA：温度上昇の基準値が「15℃」という記述は誤り。正しくは「25℃」の温度上昇が号数の基準。\nB：「1時間に何リットル」は誤り。給湯能力は「1分間に何リットル」（毎分流量）で表す。\nD：ガス消費量（kW）を10で割った値が号数というのは誤り。号数はガス消費量の指標ではなく給湯能力（水温上昇×流量）の指標。\n\n【頻出】給湯器の号数の定義（1分間に25℃上昇させられるリットル数）は機器選定・能力評価の基礎として頻出。16号・20号・24号等の標準的な号数と用途の対応も覚える。\n【混同注意】「25℃上昇」という基準（15℃の水道水を40℃に上げる想定）と「15℃上昇」を混同しないこと。号数の基準温度差（ΔT = 25℃）は正確に覚える。"
