"answer": 1,
"explanation": "ガスコード（ゴム管・内径7mm等）は可動式機器（テーブルコンロ・ガスストーブ等）への接続に使用でき、その長さは一般に1.5m以内（機器の種類・仕様によって異なる場合あり）に制限されている。長いゴム管はガス漏洩リスクが高まるため長さの制限が設けられている。\n\nA：ガスコード（ゴム管）は壁貫通部への使用は禁止されている。壁の中でのゴム管は点検・交換ができず、劣化・損傷が発見できないため危険。壁貫通部には金属管を使用する。\nC：ガスコードには耐用年数（通常3〜7年程度）があり、経年劣化（亀裂・硬化・変形）により交換が必要。「永久的・交換不要」は誤り。\nD：ガスコードはすべての機器・圧力区分に使用できるわけではなく、低圧の可動式小型機器への接続に用途が限定されている。高圧・中圧配管へのゴム管使用は禁止。\n\n【頻出】ガスコードの適正使用（可動機器接続・長さ1.5m以内・壁貫通禁止・定期交換）は施工基準・保安管理の実務として頻出。ガスコードの劣化による漏洩事故が実際に発生している。\n【混同注意】ガスコード（ゴム・樹脂製の可動用接続管）と配管用ゴムホース（より高圧用途のホース）の使用区分の違い。また金属フレキシブル管（ステンレス）は使用条件・耐久性がゴム管より優れる。"
