"explanation": "特定ガス消費機器の設置工事の監督に関する法律により、特定ガス消費機器（屋内設置型開放式ガス瞬間湯沸器・ガス風呂釜等）の設置・変更工事には、所定の講習を修了した「特定ガス消費機器設置工事監督者」の資格を持つ者が工事の監督を行うことが義務付けられている。\n\nA：特定ガス消費機器設置工事監督者の資格はガス主任技術者免状とは別の資格であり、自動的に付与されるものではない。別途講習修了・資格取得が必要。\nC：特定ガス消費機器設置工事監督者は国の法律に基づく資格制度であり、都道府県資格ではなく国家資格（経済産業大臣が登録した機関が実施する講習による）。\nD：特定ガス消費機器の設置工事には資格要件があり、無資格者が自由に行えるというのは誤り。不適切な施工によるCO中毒事故防止が制度の目的。\n\n【頻出】特定ガス消費機器設置工事監督者制度（設置工事に監督者資格が必要）はガス消費機器の設置規制として試験頻出。CO中毒事故防止のための消費者保護制度としての意義も重要。\n【混同注意】特定ガス消費機器設置工事監督者（消費機器設置法に基づく設置工事の資格）とガス主任技術者（ガス事業法に基づくガス工作物保安の資格）は根拠法・対象・職務がすべて異なる別の資格制度。"
