"explanation": "ガス栓の設置基準として、接続するガスコードが無理な曲がり・引っ張り・ねじれなしに接続できる位置・高さとすること、緊急時の遮断操作が容易な位置とすること（隠れた場所に設置しない）等が定められている。適切なガス栓位置は日常的な安全確認と緊急遮断の迅速化に不可欠。\n\nA：ガス栓は点検・操作が困難な隠れた位置への設置は推奨されない。緊急時に迅速に閉操作できることが重要であり、アクセスしやすい位置への設置が基本。\nC：ガス栓は不使用時に閉じることが安全の基本。「常時全開に固定」は誤りで、むしろ使用しない機器のガス栓は閉じておくことが基本的な安全管理。\nD：ガス栓の材質は黄銅・ステンレス等の金属製が主流であり、樹脂製のみという制限はない。用途・圧力・環境に応じた材質選定が行われる。\n\n【頻出】ガス栓の設置位置（操作容易・緊急遮断可能な位置）と使用しない際の閉操作（ガス節約・安全確保）はガス機器施工・日常管理の基礎として頻出。\n【混同注意】機器用ガス栓（器具栓：機器への接続用）とメーター前ガス栓（メインバルブ：建物全体のガス遮断用）は役割・設置場所が異なる。緊急時はメインバルブの閉止が全体遮断に有効。"
