"answer": 1,
"explanation": "ガス機器の内部構造（バーナー・安全装置・電気回路等）の修理・改造は専門的な技術・知識が必要であり、無資格者・非専門家による修理・改造は安全装置の機能損失・ガス漏洩・不完全燃焼等の重大事故につながるリスクがある。メーカーサービス・ガス事業者等の専門業者への依頼が適切。\n\nA：ガス機器の内部修理・改造を消費者が自ら行うことは安全上推奨されない。「専門業者への依頼は費用がかかるため不要」という判断は誤りで、安全性の確保が最優先。\nC：ガス機器は特定のガス種（都市ガス13A・LPG等）に合わせてバーナー・ノズル・調整弁等が設計されており、異種ガスへの転用には専門的な改造・調整が必要。消費者が自由に転用できるものではなく、誤転用は爆発・不完全燃焼の原因。\nD：ガス機器の製造番号（シリアル番号）は製品の識別・リコール情報の確認・修理部品の特定等に必要な重要情報であり、勝手に剥がすことは後の対応に支障をきたす可能性がある。\n\n【頻出】ガス機器の改造・転用の危険性（異種ガス間の転用には専門改造が必要）と専門業者による修理の重要性は消費機器保安の基本として頻出。\n【混同注意】ガス機器の「ガス種転用改造」（都市ガス↔LPG）は専門業者が実施可能な正規の改造手順があり、それに従った実施であれば可能。ただし消費者が独自に転用することは危険。"
