"explanation": "ガス機器（給湯器・コンロ・暖房機等）は使用年数の経過とともに、安全装置（熱電対・センサー等）の感度低下・ゴム部品の劣化・熱交換器のスケール蓄積・電気部品の劣化等が進行する。消費者庁・メーカーは「標準的な使用期間（概ね10〜15年）」を超えた場合の点検・交換を推奨しており、経年劣化による事故防止が目的。\n\nA：ガス機器の「法定耐用年数20年・20年未満は安全」という固定的な法令上の基準はなく、機器の種類・使用条件・保守状態によって実際の寿命は異なる。\nC：ガス機器の耐用年数は「無制限・何年でも安全」ではなく、経年劣化により保安機能が低下するリスクがある。定期点検と適切な時期での交換が重要。\nD：ガス機器の経年劣化は外観（錆・変色）だけでなく、内部部品（安全装置・熱交換器・シール材等）の目視困難な劣化が進行することが多く、外観のみで全体の状態を判断することはできない。\n\n【頻出】ガス機器の標準使用期間（目安10〜15年）と経年劣化リスク（安全装置の機能低下・ガス漏洩リスクの増大）は近年試験頻出テーマ。特に長期使用機器による事故防止の観点から重要。\n【混同注意】法定耐用年数（税務上の減価償却年数：ガス機器は6〜13年程度）と保安上の使用可能期間（機器の安全性が維持される期間）は目的・考え方が全く異なる。保安上の判断は安全機能の維持が基準となる。"
