"explanation": "ガス風呂釜（追い焚き機能付き給湯器等）には空焚き防止装置（水流センサー・水位センサー等）が搭載されており、浴槽の水位が循環口（追い焚き入口）以下になると水流が検知されなくなり、自動的に運転を停止して機器の過熱・損傷を防止する。\n\nA：空の浴槽での空焚きは熱交換器・バーナーの過熱・損傷を引き起こす危険があり、空焚き防止装置が作動して運転を停止する。「空焚き時の安全性は問題ない」は誤り。\nC：追い焚き中に給水を増やして水温を下げることは機器の動作に直接影響せず、「推奨される安全手順」として法令・基準で定められたものではない。追い焚き中の安全配慮として子どもの監視が重要。\nD：追い焚き中の保護者の浴室待機を「法令で義務付ける」規定はない。子どもの安全については保護者の自主的な配慮・監視が求められる。\n\n【頻出】ガス風呂釜の空焚き防止装置の機能（浴槽水位低下→自動停止）と空焚きの危険性（過熱・損傷）は消費機器の安全機能として頻出。\n【混同注意】空焚き防止装置（水位低下での自動停止）と過熱防止装置（機器温度上昇での自動停止）は検知対象が異なる安全装置。どちらも機器保護と使用者安全のための重要装置。"
