"answer": 1,
"explanation": "ガス事業法および同法の趣旨に基づき、一般ガス導管事業者等は需要者（消費者）に対してガスの安全な使用方法・緊急時の対応（ガス漏洩時の行動・消防・ガス事業者への連絡等）・機器の適切な使用・換気の重要性等に関する情報を積極的に提供し、保安意識の向上に寄与することが求められる。\n\nA：消費者への情報提供はガス事業者の重要な保安活動の一部であり、「すべて国が担う・事業者は義務なし」というのは誤り。ガス事業者が直接消費者と接点を持つことから事業者による啓発が最も効果的。\nC：消費者への保安情報提供は広告・宣伝とは本質的に異なる保安義務の一環であり、「保安上の義務ではない」という記述は誤り。\nD：情報提供の方法・頻度について「年1回パンフレット配布のみで足りる」というガス事業法施行規則の明示的な規定はなく、多様な方法（訪問・通知・ウェブ・緊急情報等）での継続的な情報提供が推奨される。\n\n【頻出】消費者への保安啓発（安全使用情報・緊急時対応の周知）はガス事業者の保安活動の重要な要素として試験頻出。需要者保護の観点からガス事業法が事業者に課す責務の一つ。\n【混同注意】保安啓発（保安義務としての情報提供）と商業広告（販促目的の情報発信）は目的・内容・法的根拠が異なる。保安情報の提供は事業者のガス事業法上の責務として位置づけられる。"
