"explanation": "乙種ガス主任技術者はガス事業法施行規則により、最高ガス圧力が中圧（0.1MPa以上1MPa未満）以下（高圧を除く）のガス工作物の工事・維持・運用に関する保安監督を行うことができる。都市ガス供給系統の中圧幹線導管・整圧器（ガバナ）・低圧本支管・低圧供給設備等が主な対象範囲となる。\n\nA：高圧（1MPa以上）のガス工作物（LNG基地の高圧配管・高圧ガスホルダー等）を担当できるのは甲種ガス主任技術者のみ。乙種は高圧を担当できない。\nC：低圧のみという限定は丙種ガス主任技術者の職務範囲。乙種は中圧以下（中圧＋低圧）を担当できる点が丙種との違い。\nD：製造設備のみという職務限定はなく、ガス主任技術者の種別は圧力区分による制限であり設備種別（製造・供給・消費）による制限ではない。\n\n【頻出】甲種（全圧力）・乙種（中圧以下）・丙種（低圧のみ）の職務範囲と圧力区分の境界値（高圧1MPa以上・中圧0.1〜1MPa未満・低圧0.1MPa未満）はバッチ1〜2から繰り返し出題されている最頻出事項。\n【混同注意】乙種の「中圧以下」は中圧と低圧の両方を含む（低圧を除外しない）。乙種が担当できる最高圧力は0.1MPa以上1MPa未満（中圧の上限値）であり、1MPa以上の高圧のみが対象外。"
