"explanation": "使用前検査（ガス事業法第68条・第69条）は設置・変更工事完了後に経済産業大臣または登録検査機関（経済産業大臣が登録した民間機関）が実施し、合格前の使用は禁止される。定期自主検査（同法第71条）は使用中に事業者が自ら実施し、結果を記録・保存する義務がある（立入検査での確認対象）。\n\nB：使用前検査は経済産業大臣または登録検査機関が実施する（事業者の自主実施ではない）点が定期自主検査と異なる。行政・第三者機関の関与がある。\nC：使用前検査（設置工事後に一度）と定期自主検査（使用中に定期的に）の実施タイミングが逆。使用前検査は設置後・使用開始前に実施し、定期自主検査は使用開始後の定期実施。\nD：両者は実施主体・タイミング・目的・法的根拠が異なる別の検査制度。「同一の検査」というのは誤り。\n\n【頻出】使用前検査（設置後・第三者実施・合格要件）と定期自主検査（使用中・事業者自主・記録義務）の対比はバッチ2・5・6から繰り返し出題されている横断的重要事項。\n【混同注意】登録検査機関（経済産業大臣が登録した民間検査機関）は使用前検査を実施できるが、定期自主検査は事業者が自主実施するものであり、登録検査機関への委託が義務ではない。"
