"explanation": "特定連絡管（ガス事業法第85条の2等）は異なるガス事業者の供給区域（ガスネットワーク）を接続するための管であり、その設置・使用には経済産業大臣の許可が必要とされる。異なる品質・圧力のガス系統の接続はガスの品質管理・保安に影響を与えるため、厳格な規制が設けられている。\n\nB：特定連絡管はガス供給区域間の接続管であり、都市ガスと上水道を接続するものではない（そのような接続は保安上も水質上も禁止される）。\nC：特定連絡管の工事・使用にはガス事業者の関与と経済産業大臣の許可が必要であり、需要者が自由に設置できるものではない。\nD：特定連絡管の規制はガス事業法（第85条の2等）に基づくものであり、電力事業法は関係しない。\n\n【頻出】特定連絡管（異なるガス事業者の供給区域接続管）とその許可規制は、都市ガス自由化後の事業者間接続・災害時相互融通の文脈でも重要なテーマとして近年出題が増えている。\n【混同注意】特定連絡管（異なる事業者の供給区域を接続）と一般の配管（需要者への供給管）・特定ガス導管事業の配管（単一事業者の特定区域向け）は法的位置づけが異なる。"
