"explanation": "2017年4月のガス小売全面自由化（ガス事業法等の一部改正）により、それまで地域独占だったガス小売事業への新規参入が登録制（従来は許可制）で認められた。一方、ガスのインフラ部分（導管の建設・維持管理）は自然独占的性格を持つため引き続き許可制が維持され、一般ガス導管事業者としての公益規制（供給義務・料金認可等）が存続する「参入規制の分離」が制度設計の核心。\n\nA：2017年改正以前のガス小売（都市ガスの供給）は地域独占・許可制で厳しく規制されており、「完全自由・規制なし」は誤り。改正は規制緩和（自由化）の方向への大きな転換点。\nC：ガス主任技術者制度は2017年改正以前から存在する長年の保安制度。改正で新設されたのはガス小売事業の「登録制」であり、ガス主任技術者制度の新設ではない。\nD：2017年改正はガス事業法の廃止ではなく改正（一部内容の変更・追加）。ガス事業法は現在も有効であり、保安規制・技術基準・監督制度は引き続き法令で定められている。\n\n【頻出】2017年ガス小売全面自由化の内容（登録制導入・小売参入自由化・導管規制は許可制維持）は制度全体の理解として試験頻出。「自由化」の意味が「保安規制の撤廃」ではなく「小売競争の促進」である点が重要。\n【混同注意】小売自由化（ガス小売事業への新規参入促進）と保安規制の継続（安全基準・監督制度は変わらない）は矛盾しない制度設計。自由化されたのは「誰がガスを売るか」であり、「どう安全を確保するか」は従来通り規制が続く。"
