"answer": 1,
"explanation": "PSM（プロセス安全管理）は化学プロセス・ガス設備等でのプロセス危険性（化学物質の爆発性・可燃性・毒性等）に起因する重大事故（カタストロフィックイベント：大規模爆発・大量漏洩・重篤な人的被害等）を防止するための包括的な安全管理システムである。プロセス危険性の特定・管理・レビュー・緊急対応計画等を含む14要素（OSHA PSMの場合）から構成される。\n\nA：PSMはプロセス起因の大規模事故防止を対象とし、個人的な転倒・感電等の職業安全（Occupational Safety）とは対象が異なる別の安全管理領域。両方を統合した安全管理が理想。\nC：PSMの考え方は日本においても「化学プロセスの安全管理指針」・「総合安全対策」等として参照されており、国内ガス事業にも概念として適用できる。OSHA規制の適用範囲（米国）と概念の有用性（国際的）は別の話。\nD：PSMと保安規程はそれぞれ独立した安全管理の枠組みであり、どちらかが他方を代替・免除するものではない。PSM導入は追加的な安全向上であり、法令義務を減じるものではない。\n\n【頻出】PSM（プロセス安全管理）の対象（プロセス起因の大規模事故防止）と構成要素（危険性評価・変更管理・緊急対応計画等）は石油・ガス・化学業界の保安管理として近年試験頻出のテーマ。\n【混同注意】プロセス安全（PSM：大規模プロセス事故防止）と職業安全（OS&H：作業員の個人的な怪我・疾病防止）は安全管理の異なる領域。ガス事業では両方の観点が必要で、相互に補完的。"
