"explanation": "防食基準（NACE等）において管対地電位は−0.85V（CSE基準）以下（より卑側）であることが必要。−0.3Vは−0.85Vより「貴（正の方向）」であり（−0.3 > −0.85）、防食基準を満たしていない防食不足の状態を示す。原因（被覆欠陥による防食電流損失・流電陽極の消耗・外部電源の出力不足等）を調査し、防食電流の増強または被覆補修等の対策が必要。\n\nB：−0.3Vは防食基準（−0.85V以下）よりも「貴（正側）」であり、基準を「超えている」のは過防食（過剰防食：−1.2V以下等のより卑な状態）とは逆。−0.3Vは防食不足であり過防食ではない。\nC：防食電位基準（−0.85V以下）を満たしていない−0.3Vは問題があり、「現状維持で問題なし」は誤り。防食不足が継続すれば腐食が進行するリスクがある。\nD：「負の値であれば防食基準を満たす」は誤り。防食基準は負の値の中でも特定の値（−0.85V以下）を要求する。−0.3V・−0.5V等の「負だが基準未達」の状態がある。\n\n【頻出】管対地電位と防食基準値（−0.85V CSE以下）の判断はバッチ6・7・9で繰り返し出題している最重要計算・判断問題。電位の正負と防食効果の関係を正確に理解する。\n【混同注意】防食不足（−0.85V未達：例−0.3V）・適正防食（−0.85V〜−1.2V程度）・過防食（−1.2V以下の過剰な卑側：水素脆化リスク）という3ゾーンの管理の考え方を整理する。"
