"answer": 0,
"explanation": "公益通報者保護法により、事業者の従業員（ガス主任技術者を含む）が不正行為（ガス事業法違反・保安上の重大問題等）を発見し、一定の条件（通報の内容・通報先・手順等の要件）を満たした上で行政機関等に通報した場合、解雇・降格等の不利益処分から保護される。保安上の重大問題の是正において公益通報制度が一定の安全機能を果たす。\n\nB：一定の条件を満たした公益通報（公益通報者保護法の要件）は法律によって保護されており、「いかなる状況でも禁止」は誤り。無条件の守秘義務と保安上の公益通報の権利は別の問題として整理される。\nC：公益通報者保護法はガス事業を含むすべての事業に適用されり、「ガス事業には適用されない」は誤り。食品・製造・運輸・エネルギー等幅広い業種が対象。\nD：公益通報者保護は「無条件・自動的」ではなく、法定要件（通報内容・通報先・通報方法等）を満たした場合に保護が適用される。通報内容の虚偽・要件不充足の場合は保護されない。\n\n【頻出】公益通報者保護とガス保安の関係は保安制度の社会的側面として近年出題が増えている。ガス主任技術者の法的地位（従業員かつ保安専門家）の特殊性が背景にある。\n【混同注意】ガス主任技術者の「意見陳述権」（社内で保安意見を述べる権利）と「公益通報」（外部への不正告発）は目的・手続き・保護の根拠が異なる別の制度。社内での意見陳述が尽きた後の最終手段として外部通報が検討される。"
