"explanation": "ガス事業法に基づくガス事業者の義務は大別して以下の3カテゴリに体系化できる：①供給・品質義務（供給区域内の供給義務・品質基準〔発熱量・ウォッベ指数・臭気等〕への適合・供給約款の認可取得等）、②保安義務（ガス工作物の技術基準適合維持・保安規程の制定・届出・遵守・ガス主任技術者の選任・定期自主検査・漏洩点検等）、③行政手続き義務（許可・登録・届出・報告・立入検査の受忍等）。この3分類はガス事業法の条文体系を横断的に理解する上で有用。\n\nA：ガス事業者の義務には経済的義務だけでなく、保安義務・品質義務・行政手続き義務等の多面的な義務が含まれる。「経済的義務のみ」という限定は根本的に誤り。\nC：ガス主任技術者はガス事業者（法人）が選任する保安監督の専門家であり、ガス主任技術者への委任で法人の義務がすべて代替されるわけではない。法人（事業者）自体に直接の保安義務がある（保安規程遵守義務・技術基準適合義務等は事業者に課される）。\nD：ガス事業者の義務は事業の状況変化・法令改正等に応じて変化し得るものであり、「永久固定・変更なし」は誤り。技術基準の改正・保安規程の変更届出等が継続的に発生する。\n\n【頻出】ガス事業法全体の義務体系（供給・品質・保安・行政手続き）を横断的に整理する総括問題は最終バッチの締めとして適切。試験全体の知識整理に役立つ体系的理解を確認する。\n【混同注意】法人（ガス事業者）の義務とガス主任技術者個人の職務は異なるレベルの法的義務・責任。法人が義務主体であり、ガス主任技術者はその法的義務の一部（保安監督）を担う専門家として機能する。"
